:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --primary: #6c5ce7;
  --primary-hover: #5a4bd1;
  --accent: #00cec9;
  --text: #f0f0f5;
  --text-muted: #b0b0c0;
  --border: #3d3d5c;
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image: radial-gradient(circle at 20% 30%, #2a2a40 0%, transparent 40%),
                    radial-gradient(circle at 80% 70%, #2a2a40 0%, transparent 40%);
  font-family: var(--font);
  font-size: 18px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border: 2px solid var(--border);
  border-radius: var(--radius);
  padding: 32px 28px;
  width: 100%;
  max-width: 440px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

h1 {
  font-size: 1.8rem;
  font-weight: 700;
  text-align: center;
  letter-spacing: 0.5px;
  color: var(--accent);
}

.subtitle {
  text-align: center;
  color: var(--text-muted);
  font-size: 1rem;
  margin-top: -8px;
}

.message {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 14px 16px;
  text-align: center;
  font-size: 1.1rem;
  font-weight: 600;
  min-height: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.2s, color 0.2s;
}

.message.too-high {
  color: #ff7675;
  border-color: #ff7675;
}

.message.too-low {
  color: #74b9ff;
  border-color: #74b9ff;
}

.message.correct {
  color: var(--accent);
  border-color: var(--accent);
  animation: pulse 0.6s ease;
}

@keyframes pulse {
  0% { transform: scale(1); }
  50% { transform: scale(1.05); }
  100% { transform: scale(1); }
}

.input-group {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: center;
}

.input-group label {
  font-size: 1rem;
  font-weight: 600;
  width: 100%;
}

.input-group input {
  flex: 1 1 120px;
  min-width: 0;
  padding: 12px 14px;
  font-size: 1.1rem;
  font-family: var(--font);
  color: var(--text);
  background: var(--bg);
  border: 2px solid var(--border);
  border-radius: 8px;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.input-group input:focus-visible {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(0, 206, 201, 0.3);
}

button {
  padding: 12px 20px;
  font-size: 1.1rem;
  font-weight: 700;
  font-family: var(--font);
  color: #fff;
  background: var(--primary);
  border: 2px solid transparent;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, box-shadow 0.15s;
  white-space: nowrap;
}

button:hover {
  background: var(--primary-hover);
}

button:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(108, 92, 231, 0.5);
}

button:active {
  transform: scale(0.97);
}

button.secondary {
  background: transparent;
  color: var(--accent);
  border-color: var(--accent);
}

button.secondary:hover {
  background: rgba(0, 206, 201, 0.1);
}

button.secondary:focus-visible {
  box-shadow: 0 0 0 3px rgba(0, 206, 201, 0.4);
}

.status-bar {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  font-size: 1rem;
  color: var(--text-muted);
}

#guessCount {
  font-weight: 600;
  color: var(--text);
}

@media (max-width: 400px) {
  .card {
    padding: 24px 18px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .input-group input {
    flex: 1 1 100%;
  }
  button {
    width: 100%;
  }
  .status-bar {
    flex-direction: column;
    align-items: stretch;
  }
}

(function () {
  'use strict';

  const guessInput = document.getElementById('guessInput');
  const guessBtn = document.getElementById('guessBtn');
  const newGameBtn = document.getElementById('newGameBtn');
  const messageEl = document.getElementById('message');
  const guessCountEl = document.getElementById('guessCount');

  let targetNumber;
  let guessCount;
  let gameOver;

  function resetGame() {
    targetNumber = Math.floor(Math.random() * 100) + 1;
    guessCount = 0;
    gameOver = false;
    guessInput.value = '';
    guessInput.disabled = false;
    guessBtn.disabled = false;
    guessInput.focus();
    messageEl.textContent = 'Make your first guess!';
    messageEl.className = 'message';
    guessCountEl.textContent = 'Guesses: 0';
  }

  function handleGuess() {
    if (gameOver) return;

    const raw = guessInput.value.trim();
    if (raw === '') {
      messageEl.textContent = 'Please enter a number.';
      messageEl.className = 'message';
      guessInput.focus();
      return;
    }

    const guess = Number(raw);
    if (!Number.isInteger(guess) || guess < 1 || guess > 100) {
      messageEl.textContent = 'Enter a whole number between 1 and 100.';
      messageEl.className = 'message';
      guessInput.focus();
      return;
    }

    guessCount++;
    guessCountEl.textContent = `Guesses: ${guessCount}`;

    if (guess === targetNumber) {
      messageEl.textContent = `Correct! You got it in ${guessCount} ${guessCount === 1 ? 'guess' : 'guesses'}.`;
      messageEl.className = 'message correct';
      gameOver = true;
      guessInput.disabled = true;
      guessBtn.disabled = true;
    } else if (guess > targetNumber) {
      messageEl.textContent = 'Too high!';
      messageEl.className = 'message too-high';
      guessInput.value = '';
      guessInput.focus();
    } else {
      messageEl.textContent = 'Too low!';
      messageEl.className = 'message too-low';
      guessInput.value = '';
      guessInput.focus();
    }
  }

  guessBtn.addEventListener('click', handleGuess);

  guessInput.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') {
      e.preventDefault();
      handleGuess();
    }
  });

  newGameBtn.addEventListener('click', resetGame);

  resetGame();
})();
